@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* Kanban Glass — derived from a light project-board UI.
     Soft off-white board, white draggable cards that lift on a gentle shadow,
     an indigo signature accent, and multi-hue category labels. */

  /* Off-white board background, faint cool tint */
  --background: oklch(0.975 0.004 250);
  --foreground: oklch(0.24 0.012 262);

  /* Card surface — pure white cards on the board */
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.24 0.012 262);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.24 0.012 262);

  /* Indigo — the board's signature accent (selection, focus, primary CTA, charts) */
  --primary: oklch(0.55 0.17 265);
  --primary-foreground: oklch(0.99 0.003 250);

  /* Faint cool-grey chips */
  --secondary: oklch(0.965 0.004 250);
  --secondary-foreground: oklch(0.30 0.012 262);

  --muted: oklch(0.965 0.004 250);
  --muted-foreground: oklch(0.56 0.012 262);

  --accent: oklch(0.55 0.17 265 / 0.10);
  --accent-foreground: oklch(0.45 0.16 265);

  --destructive: oklch(0.58 0.20 25);
  --destructive-foreground: oklch(0.99 0.003 250);

  --border: oklch(0 0 0 / 0.08);
  --input: oklch(0 0 0 / 0.05);
  --ring: oklch(0.55 0.17 265 / 0.45);

  /* Friendly medium-large radius — the cards' soft corners */
  --radius: 0.875rem;

  /* ─── Multi-hue category labels (the board's colored tags) ───
     Reused as Badge variants and as the categorical chart palette. */
  --label-high: oklch(0.64 0.19 25);        /* coral red  — "High"   */
  --label-high-soft: oklch(0.64 0.19 25 / 0.12);
  --label-high-ink: oklch(0.50 0.18 25);
  --label-medium: oklch(0.78 0.15 75);      /* amber      — "Medium" */
  --label-medium-soft: oklch(0.78 0.15 75 / 0.16);
  --label-medium-ink: oklch(0.55 0.13 70);
  --label-low: oklch(0.70 0.13 158);        /* green      — "Low"    */
  --label-low-soft: oklch(0.70 0.13 158 / 0.14);
  --label-low-ink: oklch(0.48 0.11 158);
  --label-info: oklch(0.62 0.15 252);       /* blue       — info     */
  --label-info-soft: oklch(0.62 0.15 252 / 0.12);
  --label-info-ink: oklch(0.48 0.15 252);
  --label-grape: oklch(0.58 0.18 302);      /* purple                */
  --label-grape-soft: oklch(0.58 0.18 302 / 0.12);
  --label-grape-ink: oklch(0.46 0.17 302);

  /* ─── Soft card-lift shadows ───
     Low-alpha, gently spread so white cards float above the board.
     Deliberately subtle (alpha 0.05–0.14); nothing should read as harsh. */
  --shadow-2xs: 0 0.0625rem 0.0625rem oklch(0.55 0.05 262 / 0.05);
  --shadow-xs:  0 0.0625rem 0.125rem oklch(0.55 0.05 262 / 0.06);
  --shadow-sm:  0 0.0625rem 0.125rem oklch(0.55 0.05 262 / 0.06), 0 0.125rem 0.375rem oklch(0.55 0.05 262 / 0.05);
  --shadow:     0 0.125rem 0.5rem oklch(0.55 0.05 262 / 0.07);
  --shadow-md:  0 0.25rem 0.875rem oklch(0.55 0.05 262 / 0.08);
  --shadow-lg:  0 0.5rem 1.5rem oklch(0.55 0.05 262 / 0.10);
  --shadow-xl:  0 0.875rem 2.25rem oklch(0.55 0.05 262 / 0.12);

  /* Card-lift — the resting elevation of a draggable card */
  --shadow-card:
    0 0.0625rem 0.125rem oklch(0.55 0.05 262 / 0.06),
    0 0.25rem 0.75rem oklch(0.55 0.05 262 / 0.08);
  /* Card-lift, raised — what a card looks like while being dragged / hovered */
  --shadow-card-hover:
    0 0.125rem 0.25rem oklch(0.55 0.05 262 / 0.07),
    0 0.75rem 1.75rem oklch(0.55 0.05 262 / 0.14);

  /* Single popover/overlay shadow shared by all floating surfaces
     (dropdown, select, popover, context-menu, tooltip, hover-card, menubar,
     command, navigation-menu) so they read as one material. */
  --shadow-overlay:
    0 0 0 0.0625rem oklch(0 0 0 / 0.05),
    0 0.625rem 1.875rem oklch(0.55 0.05 262 / 0.14);

  /* Filled-control material — the SAME treatment the primary Button uses,
     scaled down. Indigo fill, a thin top specular highlight, a soft lift.
     Reused by checkbox (checked), switch (track), radio (ring), slider (range). */
  --primary-rim: color-mix(in oklch, var(--primary) 72%, white 28%);
  --shadow-primary-inset:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.30),
    inset 0 0 0.625rem var(--primary-rim),
    0 0.125rem 0.3125rem oklch(0.45 0.16 265 / 0.30);
  --shadow-primary-inset-sm:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.32),
    inset 0 0 0.375rem var(--primary-rim),
    0 0.0625rem 0.1875rem oklch(0.45 0.16 265 / 0.28);

  /* ─── Chart palette: the board's multi-hue labels (categorical) ─── */
  --chart-1: var(--label-info);
  --chart-2: var(--label-low);
  --chart-3: var(--label-medium);
  --chart-4: var(--label-high);
  --chart-5: var(--label-grape);

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.25rem);
  --radius-md: calc(var(--radius) - 0.125rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.25rem);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family:
      "Inter",
      ui-sans-serif,
      system-ui,
      -apple-system,
      BlinkMacSystemFont,
      "Segoe UI",
      Roboto,
      "Helvetica Neue",
      Arial,
      sans-serif;
    letter-spacing: -0.005em;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  /* Let textareas grow with their content instead of nested scrolling:
     smoother writing, easier-to-scan forms. */
  textarea {
    /* Fallback for browsers without field-sizing (e.g. Firefox): keep the
       textarea user-resizable so it can still be grown manually. */
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: comfortable;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 56);
  --layout-inset: calc(var(--spacing, 0.25rem) * 6);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 8);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 5);
}

